import type { Readable } from 'node:stream';
import { config } from '@docly/config';
import { LocalStorageProvider } from './local-storage-provider.js';

// Object-storage abstraction (spec section 80): the document domain talks to
// this interface only, so the backing store (local disk now, S3/MinIO later)
// can be swapped without touching the document service or its tests.
export interface StorageProvider {
  // Stores `data` under `key`. Keys are generated by the server, never
  // derived from user input.
  upload(key: string, data: Buffer): Promise<void>;
  // Streams the stored object. Rejects with StorageObjectNotFoundError when
  // the key doesn't exist.
  download(key: string): Promise<Readable>;
  // Idempotent: deleting a missing key is not an error.
  delete(key: string): Promise<void>;
}

export class StorageObjectNotFoundError extends Error {
  constructor(key: string) {
    super(`Stored object not found: ${key}`);
    this.name = 'StorageObjectNotFoundError';
  }
}

let provider: StorageProvider | null = null;

export function getStorage(): StorageProvider {
  provider ??= new LocalStorageProvider(config.STORAGE_DIR);
  return provider;
}

// Lets tests inject an in-memory or failing provider.
export function setStorageForTesting(next: StorageProvider | null): void {
  provider = next;
}
